                synchronized (processedPayments) {
                    processedPayments.put(paymentKey, new PaymentProcessingResult(true, null));
                }
                return order;
            }
            synchronized (processedPayments) {
                processedPayments.put(paymentKey, new PaymentProcessingResult(false, ErrorCode.OPERATION_NOT_ALLOWED));
